parts.text:
[
  {
    "statement": "Forest canopy opening through clearing, coppicing, and thinning has differential effects on butterfly and moth communities.",
    "citations": []
  },
  {
    "statement": "Thinning trees within forests generally increases butterfly species richness and abundance.",
    "citations": [
      "3940"
    ]
  },
  {
    "statement": "Coniferous woodland thinned along with prescribed burning, mulching, or nearby felling had greater species richness of butterflies compared to unmanaged woodland.",
    "citations": [
      "3940"
    ]
  },
  {
    "statement": "Coniferous woodland thinned along with prescribed burning, mulching, or nearby felling had a higher abundance of all butterflies or specialist butterflies compared to unmanaged woodland.",
    "citations": [
      "3940"
    ]
  },
  {
    "statement": "Partially-cleared forest plots had higher butterfly species richness than closed-canopy forest.",
    "citations": [
      "3940"
    ]
  },
  {
    "statement": "Partially-cleared forest plots had lower moth species richness than closed-canopy forest.",
    "citations": [
      "3940"
    ]
  },
  {
    "statement": "Clearing or opening patches in forests shows mixed effects depending on the taxa and patch characteristics.",
    "citations": []
  },
  {
    "statement": "Cleared patches had greater species richness of butterflies than unmanaged patches or closed canopy forest.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "Cleared patches had lower species richness of moths than unmanaged patches or closed canopy forest.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "Larger cleared patches supported higher species richness and abundance of butterflies than undisturbed forest.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "Smaller cleared patches did not show a higher species richness and abundance of butterflies compared to undisturbed forest.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "Cleared patches generally had a higher abundance of butterflies compared to before management or in unmanaged areas.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "Cleared patches had a higher abundance of specific butterfly species like chequered blue, woodland brown, high brown fritillary, and small pearl-bordered fritillary, compared to before management or in unmanaged areas.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "A review across Europe reported that clearing small patches in forests benefitted 19 out of 67 butterfly species of conservation concern.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "Coppicing woodland creates varying effects based on the age of the coppice.",
    "citations": []
  },
  {
    "statement": "Coppiced woodland had greater species richness of butterflies than unmanaged woodland.",
    "citations": [
      "3939"
    ]
  },
  {
    "statement": "Coppiced woodland had lower species richness of macro-moths than mature forest.",
    "citations": [
      "3939"
    ]
  },
  {
    "statement": "The abundance of butterflies was higher in woodland coppiced 2-4, 5-7, or 12-15 years ago than in woodland coppiced over 15 years ago.",
    "citations": [
      "3939"
    ]
  },
  {
    "statement": "Heath fritillary populations were more likely to persist for up to 20 years in coppiced woodland than in mature conifer woodland.",
    "citations": [
      "3939"
    ]
  },
  {
    "statement": "Alternative harvesting methods show different impacts compared to clearcutting.",
    "citations": []
  },
  {
    "statement": "Thinning resulted in higher macro-moth species richness than patch-cutting or clearcutting.",
    "citations": [
      "3868"
    ]
  },
  {
    "statement": "Macro-moth species richness in thinned forests was similar to richness in unharvested forest.",
    "citations": [
      "3868"
    ]
  },
  {
    "statement": "Selective logging produced similar species richness of moths to group selection harvesting or clearcutting.",
    "citations": [
      "3867"
    ]
  },
  {
    "statement": "Selective logging produced lower species richness of moths than unharvested forest.",
    "citations": [
      "3867"
    ]
  },
  {
    "statement": "Selectively logged forests had a higher abundance of exposed moth caterpillars compared to clearcut forests.",
    "citations": [
      "3867"
    ]
  },
  {
    "statement": "Selectively logged forests had a similar abundance of concealed moth caterpillars compared to clearcut forests.",
    "citations": [
      "3867"
    ]
  }
]

[
  {
    "statement": "Both rotational burning and leaving unburned patches during prescribed fires show benefits for butterfly populations in prairies.",
    "citations": [
      "3879",
      "3883",
      "3882"
    ]
  },
  {
    "statement": "The abundance of Karner blue butterflies increased over 2-3 years in oak savannas and prairies where unburned patches were left during prescribed burning.",
    "citations": [
      "3879"
    ]
  },
  {
    "statement": "Six out of nine specialist butterfly species were more abundant at sites with unburned areas compared to sites without unburned areas.",
    "citations": [
      "3879"
    ]
  },
  {
    "statement": "One specialist butterfly species was less abundant at sites with unburned areas compared to sites without unburned areas.",
    "citations": [
      "3879"
    ]
  },
  {
    "statement": "Two specialist butterfly species had similar abundance at sites with unburned areas compared to sites without unburned areas.",
    "citations": [
      "3879"
    ]
  },
  {
    "statement": "Karner blue butterflies were recorded using all 11 unburned patches surveyed within oak savannas and prairies managed by burning.",
    "citations": [
      "3879"
    ]
  },
  {
    "statement": "The total abundance of prairie specialist, grassland and all butterflies was higher on prairies burned more than one, two or four years ago than on prairies burned in the last one or two years under rotational burning management.",
    "citations": [
      "3883"
    ]
  },
  {
    "statement": "The abundance of grassland and generalist butterflies was highest in the third year after burning.",
    "citations": [
      "3883"
    ]
  },
  {
    "statement": "The abundance of migrant butterflies was highest in the first year after burning.",
    "citations": [
      "3883"
    ]
  },
  {
    "statement": "Two studies found that pine-oak barrens and prairies managed by rotational burning every 2-5 years had a higher total abundance of butterflies than unmanaged sites.",
    "citations": [
      "3883"
    ]
  },
  {
    "statement": "Rotational burning showed mixed effects across different studies.",
    "citations": [
      "3883"
    ]
  },
  {
    "statement": "Some studies found lower abundance of butterflies in rotationally burned prairies compared to unmanaged areas in certain regions.",
    "citations": [
      "3883"
    ]
  },
  {
    "statement": "Regal fritillary abundance was higher in grasslands managed by rotational burning every three years than on unmanaged sites.",
    "citations": [
      "3882",
      "3883"
    ]
  },
  {
    "statement": "The abundance of Regal fritillary butterflies was higher in rotationally burned prairies four years after the last burn than one or eight years after the last burn.",
    "citations": [
      "3882",
      "3883"
    ]
  },
  {
    "statement": "Some studies found that regal fritillary and arogos skipper butterflies were less abundant in burned prairies compared to hayed prairies.",
    "citations": [
      "3882",
      "3883"
    ]
  },
  {
    "statement": "Karner blue butterfly abundance was similar in rotationally burned and unmanaged oak savannas and prairies.",
    "citations": [
      "3882",
      "3883"
    ]
  },
  {
    "statement": "Both rotational burning and leaving unburned patches provide refugia and recovery opportunities for butterfly populations.",
    "citations": [
      "3879",
      "3882",
      "3883"
    ]
  },
  {
    "statement": "The timing since the last burn appears critical for the effectiveness of rotational burning.",
    "citations": [
      "3882",
      "3883"
    ]
  },
  {
    "statement": "Unburned patches provide immediate refugia for butterfly populations during active burning periods.",
    "citations": [
      "3879"
    ]
  }
]

[
  {
    "statement": "Several specific lighting modification actions are available to mitigate negative impacts of artificial lighting on moth populations.",
    "citations": []
  },
  {
    "statement": "Using shielded \"full cut-off\" lights to remove outwards lighting was found to attract fewer individual moths and moth species compared to conventional lights without blinds or filters.",
    "citations": [
      "3904"
    ]
  },
  {
    "statement": "Using low intensity lighting reduced moth attraction compared to higher intensity lights.",
    "citations": [
      "3902"
    ]
  },
  {
    "statement": "Fewer moths were attracted to low intensity lights that emitted a narrower range of yellow light with little UV compared to higher intensity lights with broader spectra including UV.",
    "citations": [
      "3902"
    ]
  },
  {
    "statement": "Using 'warmer' red or yellow lighting rather than other lighting colors significantly reduced moth attraction.",
    "citations": [
      "3906"
    ]
  },
  {
    "statement": "Fewer individual moths and moth species were attracted to yellow, green, white, or red lights compared to UV, actinic, blue, or conventional metal halide lights.",
    "citations": [
      "3906"
    ]
  },
  {
    "statement": "One study found that four moth species spent more time feeding under red lights than under white or green lights.",
    "citations": [
      "3906"
    ]
  },
  {
    "statement": "One study found that four moth species spent less time feeding under red, white, or green lights than when in complete darkness.",
    "citations": [
      "3906"
    ]
  },
  {
    "statement": "Restricting the use of polarized light is a potentially beneficial action for butterfly and moth conservation, though this intervention has not yet been evaluated by studies.",
    "citations": [
      "3903"
    ]
  },
  {
    "statement": "Using glazing treatments to reduce light spill from inside lit buildings is a potentially beneficial action for butterfly and moth conservation, though this intervention has not yet been evaluated by studies.",
    "citations": [
      "3905"
    ]
  },
  {
    "statement": "Restricting the timing of lighting to conserve areas with natural light regimes is a potentially beneficial action for butterfly and moth conservation, though this intervention has not yet been evaluated by studies.",
    "citations": [
      "3901"
    ]
  },
  {
    "statement": "Minimizing road lighting to reduce insect attraction is a potentially beneficial action for butterfly and moth conservation, though this intervention has not yet been evaluated by studies.",
    "citations": [
      "3852"
    ]
  },
  {
    "statement": "Removing or changing turbine lighting to reduce insect attraction is a potentially beneficial action for butterfly and moth conservation, though this intervention has not yet been evaluated by studies.",
    "citations": [
      "3843"
    ]
  }
]

[
  {
    "statement": "The long-term success of re-establishing butterfly populations through translocation or captive-release shows mixed results.",
    "citations": []
  },
  {
    "statement": "For translocation programs within a species' former range, eight studies reported that translocated populations persisted for 2-12 years and increased in abundance.",
    "citations": [
      "3909"
    ]
  },
  {
    "statement": "Three studies found that while some translocated populations persisted for 1-49 years and increased in abundance, other populations died out within 0-7 years.",
    "citations": [
      "3909"
    ]
  },
  {
    "statement": "A review across the UK and Ireland found that only 25% of translocated and released captive-bred butterfly populations survived for at least three years.",
    "citations": [
      "3909"
    ]
  },
  {
    "statement": "A review across the UK and Ireland found that 38% of translocated and released captive-bred butterfly populations died out within a three-year timeframe.",
    "citations": [
      "3909"
    ]
  },
  {
    "statement": "A review across the UK and Ireland found that only 8% of translocated and released captive-bred butterfly populations survived for more than 10 years.",
    "citations": [
      "3909"
    ]
  },
  {
    "statement": "Another review reported that translocated large copper populations survived for up to 38 years but ultimately died out or required supplementation by further releases.",
    "citations": [
      "3909"
    ]
  },
  {
    "statement": "For translocations outside a species' known range, two of three studies reported populations persisting and increasing in abundance over 8 and 28 years.",
    "citations": [
      "3911"
    ]
  },
  {
    "statement": "For translocations outside a species' known range, one population died out within one year.",
    "citations": [
      "3911"
    ]
  },
  {
    "statement": "For captive-bred releases, six studies reported populations persisting for 2-28 years and increasing in abundance.",
    "citations": [
      "3914"
    ]
  },
  {
    "statement": "For captive-bred releases, two studies found populations died out after 1, 2, or 12 years or required further releases to survive.",
    "citations": [
      "3914"
    ]
  },
  {
    "statement": "One study found that three of ten captive-bred populations became established.",
    "citations": [
      "3914"
    ]
  },
  {
    "statement": "One study found that at least one established captive-bred population persisted for five years.",
    "citations": [
      "3914"
    ]
  },
  {
    "statement": "A review found that 25% of captive-bred populations survived for more than 3 years.",
    "citations": [
      "3914"
    ]
  },
  {
    "statement": "A review found that 38% of captive-bred populations died out within 3 years.",
    "citations": [
      "3914"
    ]
  },
  {
    "statement": "A review found that only 8% of captive-bred populations survived for more than 10 years.",
    "citations": [
      "3914"
    ]
  },
  {
    "statement": "Released captive-bred caterpillars showed lower survival rates than wild or translocated caterpillars.",
    "citations": [
      "3914"
    ]
  }
]

[
  {
    "statement": "Several actions can be taken in urban environments to support butterfly and moth populations.",
    "citations": []
  },
  {
    "statement": "Planting parks, gardens and road verges with appropriate native species shows positive effects for butterfly and moth populations.",
    "citations": [
      "3842"
    ]
  },
  {
    "statement": "Gardens and road verges planted with native species have greater species richness of butterfly and moth adults and caterpillars than areas with mixed or exclusively non-native plant species.",
    "citations": [
      "3842"
    ]
  },
  {
    "statement": "Gardens and road verges planted with native species have a higher abundance of butterfly and moth caterpillars than areas with mixed or exclusively non-native plant species.",
    "citations": [
      "3842"
    ]
  },
  {
    "statement": "Wildlife gardening practices can help support butterfly and moth populations.",
    "citations": [
      "3834"
    ]
  },
  {
    "statement": "Gardens where insecticides and herbicides were not used had higher butterfly abundance.",
    "citations": [
      "3834"
    ]
  },
  {
    "statement": "Stopping the use of pesticides as seed dressings and sprays in flower beds and greenspaces is beneficial to butterfly and moth populations.",
    "citations": [
      "3900"
    ]
  },
  {
    "statement": "Gardens where insecticides and herbicides were not used had a higher abundance of butterflies.",
    "citations": [
      "3900"
    ]
  },
  {
    "statement": "Altering mowing regimes on greenspaces and road verges provides significant benefits to butterfly and moth populations.",
    "citations": [
      "3841"
    ]
  },
  {
    "statement": "Less frequently mown or unmown urban greenspaces have higher species richness and diversity of butterflies and moths than more frequently mown areas.",
    "citations": [
      "3841"
    ]
  },
  {
    "statement": "Unmown public parks have a higher abundance of all adult butterflies than regularly mown areas.",
    "citations": [
      "3841"
    ]
  },
  {
    "statement": "Creating nectar flower mixtures and wildflower strips is effective for supporting butterfly and moth populations.",
    "citations": [
      "3932"
    ]
  },
  {
    "statement": "Sown wildflower strips have higher species richness and diversity of butterflies and moths than conventional field margins, unsown margins, and cropped fields.",
    "citations": [
      "3932"
    ]
  },
  {
    "statement": "Sown wildflower strips have a higher abundance of butterflies than conventional field margins, unsown margins, and cropped fields.",
    "citations": [
      "3932"
    ]
  }
]

[
  {
    "statement": "In the USA, different timber harvesting methods show varying impacts on moth diversity compared to clearcutting.",
    "citations": []
  },
  {
    "statement": "The species richness of macro-moths was found to be higher after shelterwood harvesting than after patch-cutting or clearcutting.",
    "citations": [
      "3871"
    ]
  },
  {
    "statement": "The species richness of macro-moths after shelterwood harvesting was found to be similar to that in thinned and unharvested forests.",
    "citations": [
      "3871"
    ]
  },
  {
    "statement": "Shelterwood harvesting resulted in similar moth species richness to single tree harvesting, group selection harvesting, or clearcutting.",
    "citations": [
      "3871"
    ]
  },
  {
    "statement": "Shelterwood harvesting resulted in lower moth species richness than unharvested forest.",
    "citations": [
      "3871"
    ]
  },
  {
    "statement": "Moth species richness recovered faster after shelterwood harvesting than after group selection harvesting or clearcutting.",
    "citations": [
      "3871"
    ]
  },
  {
    "statement": "Forests harvested by single tree selection had similar species richness of moths to forests managed by group selection harvesting or clearcutting.",
    "citations": [
      "3867"
    ]
  },
  {
    "statement": "Forests harvested by single tree selection had lower species richness of moths than unharvested forest.",
    "citations": [
      "3867"
    ]
  },
  {
    "statement": "The species richness of macro-moths was higher after thinning than after patch-cutting or clearcutting.",
    "citations": [
      "3868"
    ]
  },
  {
    "statement": "The species richness of macro-moths after thinning was similar to the richness in unharvested forest.",
    "citations": [
      "3868"
    ]
  },
  {
    "statement": "Studies found group selection harvesting resulted in a similar species richness of moths to single tree harvesting or clearcutting.",
    "citations": [
      "3868"
    ]
  },
  {
    "statement": "Group selection harvesting resulted in lower moth richness than unharvested forest.",
    "citations": [
      "3868"
    ]
  },
  {
    "statement": "Recovery rates for moth species richness after group selection harvesting were similar to recovery rates after clearcutting.",
    "citations": [
      "3868"
    ]
  },
  {
    "statement": "Recovery rates for moth species richness after group selection harvesting were slower than recovery rates after shelterwood harvesting.",
    "citations": [
      "3868"
    ]
  }
]

[
  {
    "statement": "Management of linear features like road verges and power lines has various effects on butterflies and moths depending on the method used.",
    "citations": []
  },
  {
    "statement": "Power line management through mechanical cutting increases butterfly species richness and abundance compared to unmanaged land.",
    "citations": [
      "3855"
    ]
  },
  {
    "statement": "The highest butterfly species richness on power lines occurs 2-4 years after scrub and tree clearance.",
    "citations": [
      "3855"
    ]
  },
  {
    "statement": "The timing of power line management is important for butterfly populations.",
    "citations": [
      "3855"
    ]
  },
  {
    "statement": "Areas of power lines cleared 2-4 years earlier support higher butterfly abundance than those cleared 1 year or 6-8 years earlier.",
    "citations": [
      "3855"
    ]
  },
  {
    "statement": "Chequered skipper abundance is higher in areas of power lines cleared two or fewer years ago than in areas cut four or more years earlier.",
    "citations": [
      "3855"
    ]
  },
  {
    "statement": "Stopping herbicide use on road verges benefits butterflies and moths.",
    "citations": [
      "3899"
    ]
  },
  {
    "statement": "Restored roadside prairies with restricted herbicide application show greater butterfly species richness, abundance, and lower mortality risk compared to verges dominated by non-native weeds with unrestricted herbicide use.",
    "citations": [
      "3899"
    ]
  },
  {
    "statement": "Transmission lines that are neither sprayed nor mown have a greater abundance of northern pearl crescent and pearl crescent butterflies compared to sprayed and mown areas.",
    "citations": [
      "3899"
    ]
  },
  {
    "statement": "Mowing regimes significantly affect butterfly and moth communities.",
    "citations": [
      "3841"
    ]
  },
  {
    "statement": "Urban greenspaces and road verges that are mown less frequently or not at all have higher species richness and diversity of butterflies and moths than frequently mown areas.",
    "citations": [
      "3841"
    ]
  },
  {
    "statement": "Road verges mown less frequently or later in summer have fewer dead butterflies killed by traffic than more frequently or earlier mown verges.",
    "citations": [
      "3841"
    ]
  },
  {
    "statement": "Roadsides mown in late summer support more ringlet butterflies than those mown in mid-summer.",
    "citations": [
      "3841"
    ]
  },
  {
    "statement": "Rotational mowing provides substantial benefits for butterflies and moths.",
    "citations": [
      "3966"
    ]
  },
  {
    "statement": "Grasslands managed by mowing strips in alternate years or mowing parts of sites at different times show greater species richness and diversity of butterflies than grasslands cut completely once per year.",
    "citations": [
      "3966"
    ]
  },
  {
    "statement": "Rotationally mown grasslands support higher butterfly and burnet moth abundance than grasslands cut in full.",
    "citations": [
      "3966"
    ]
  },
  {
    "statement": "A study found that 29 out of 32 butterfly species prefer meadows half-mown in June and August to meadows cut completely twice per year.",
    "citations": [
      "3966"
    ]
  },
  {
    "statement": "Restoring species-rich grasslands along road verges enhances butterfly and moth communities.",
    "citations": [
      "3854"
    ]
  },
  {
    "statement": "Restored roadside prairies and verges sown with native wildflowers, more butterfly larval food plants, and more plant species support higher species richness and diversity of butterflies and moths compared to verges dominated by non-native vegetation.",
    "citations": [
      "3854"
    ]
  },
  {
    "statement": "Wide road verges support higher butterfly species richness and abundance than narrow road verges.",
    "citations": [
      "3854"
    ]
  },
  {
    "statement": "Reducing cutting frequency generally benefits butterflies and moths.",
    "citations": [
      "3961"
    ]
  },
  {
    "statement": "Meadows cut once per year have higher species richness of butterflies and moths than meadows cut two or more times per year.",
    "citations": [
      "3961"
    ]
  },
  {
    "statement": "Meadows cut occasionally or once per year support higher abundance of certain species like the Scotch argus compared to intensively mown grasslands.",
    "citations": [
      "3961"
    ]
  }
]

[
  {
    "statement": "The documented effects of excluding different types of herbivores on butterfly and moth populations show mixed but generally positive outcomes.",
    "citations": []
  },
  {
    "statement": "For vertebrate herbivore exclusion, five of eight studies found that forest and grassland plots fenced to exclude or reduce the density of deer, sheep, pigs and large herbivores had a higher abundance of butterflies, moths, caterpillars, rare macro-moths and New Forest burnet moths than unfenced plots.",
    "citations": [
      "3891"
    ]
  },
  {
    "statement": "Two of four replicated studies found that forest plots fenced to exclude or reduce the density of non-native pigs and deer had greater species richness of butterflies and macro-moths than unfenced plots.",
    "citations": [
      "3891"
    ]
  },
  {
    "statement": "Two studies found that forest plots fenced to exclude elk had mixed effects on species richness and abundance of butterflies and arthropods, including moths, depending on fire intensity and year.",
    "citations": [
      "3891"
    ]
  },
  {
    "statement": "One study found that grassland plots fenced to exclude elk had similar species richness and abundance of butterflies to unfenced plots in all years.",
    "citations": [
      "3891"
    ]
  },
  {
    "statement": "A global systematic review found that reducing or removing grazing or browsing by wild or domestic herbivores in temperate and boreal forests increased the abundance of butterflies and moths.",
    "citations": [
      "3891"
    ]
  },
  {
    "statement": "A global systematic review found that reducing or removing grazing or browsing by wild or domestic herbivores in temperate and boreal forests did not affect species richness.",
    "citations": [
      "3891"
    ]
  },
  {
    "statement": "All Glanville fritillary caterpillar nests survived in grassland fenced to exclude sheep, compared to 88% survival in grazed areas.",
    "citations": [
      "3891"
    ]
  },
  {
    "statement": "Fewer Glanville fritillary caterpillar nests were damaged in fenced areas compared to grazed areas.",
    "citations": [
      "3891"
    ]
  },
  {
    "statement": "One study found a higher density of pearl-bordered fritillary butterflies at sites fenced to exclude grazing animals than at unfenced sites.",
    "citations": [
      "3885"
    ]
  },
  {
    "statement": "Wet meadows managed by light grazing with cattle or horses had similar butterfly species richness and abundance compared to mowing management.",
    "citations": [
      "3971"
    ]
  },
  {
    "statement": "Bog fritillaries showed lower numbers and reduced use of areas after cattle grazing began.",
    "citations": [
      "3971"
    ]
  }
]

[
  {
    "statement": "Grassland restoration from arable land generally shows positive outcomes for butterfly communities.",
    "citations": [
      "3929"
    ]
  },
  {
    "statement": "Grasslands restored from arable land developed butterfly communities that became increasingly similar to existing high-quality grasslands over the first 10 years after establishment.",
    "citations": [
      "3929"
    ]
  },
  {
    "statement": "Four to five-year-old created grasslands and abandoned cropland have greater species richness of butterflies than conventionally managed grassland or cultivated farms.",
    "citations": [
      "3929"
    ]
